import java.util.*;
public class MyJava {
   public static int fun( int x )
   {
   if( x > 10 )
       return  (3*x+5);
                         //base step
   else
       return fun( x +2 ) -3; //recursive step
   }
   public static void main (String args[]) {
       System.out.print("the result of fun(5) =  " + fun( 5 ) );
   }
}

