package myjava;
import java.util.*;
public class MyJava {
    public static int Fib(int n){
      if(n<=1)
            return n;
      else
            return (Fib(n-1)+Fib(n-2));
    }
    public static void main (String args[]) {
      int x =5;
      System.out.println("the Fib of " +x + " equal to "+ Fib( x ) );
    }
}

